#include "evengine/studio.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace evengine;
int main(int argc,char** argv){try{
 if(argc!=3)throw std::runtime_error("Expected project and output directory");StudioGame g(argv[1]);int checks=0;auto check=[&](bool ok,const char* name){if(!ok)throw std::runtime_error(name);checks++;std::cout<<"OK "<<name<<'\n';};
 auto press=[&](Action a){Input in;in.set(a,true);g.update(in,Tick);};auto npc=[&](std::string scene,std::string id)->const Object&{for(auto& o:g.project.scenes.at(scene).objects)if(o.id==id)return o;throw std::runtime_error("NPC missing");};
 check(g.quests.size()==1&&g.questState("keepers-errand")=="available","quest begins available");
 g.interact(npc("meadow","keeper"));check(g.dialogueNode=="greeting"&&g.availableChoices().size()==1,"only the available-quest choice is shown");auto feet=g.feet;press(Action::Right);check(g.feet.x==feet.x,"branching conversation pauses movement");
 press(Action::Interact);check(g.questState("keepers-errand")=="active"&&g.dialogueNode=="accepted","accept choice starts quest and advances node");check(!g.acceptQuest("keepers-errand"),"accepted quests cannot restart");press(Action::Interact);check(g.dialogueObject.empty(),"end destination closes conversation");
 press(Action::Journal);check(g.journalOpen,"J opens the journal");feet=g.feet;press(Action::Right);check(g.feet.x==feet.x,"journal pauses movement");press(Action::Quit);check(!g.journalOpen&&!g.quit,"Escape closes journal before quitting");
 g.interact(npc("meadow","keeper"));press(Action::Interact);check(g.dialogueNode=="progress"&&g.availableChoices().size()==2,"turn-in choice hidden before objectives complete");press(Action::Down);check(g.dialogueChoice==1,"down selects next visible choice");press(Action::Interact);check(g.dialogueObject.empty(),"selected branch is followed");
 check(!g.completeQuest("keepers-errand")&&g.inventory.empty(),"early turn-in rejects without rewards");
 g.activated.insert("meadow:garden-gate");Input idle;g.update(idle,Tick);check(g.objectiveDone("keepers-errand",0),"activated gate records objective");g.scene="grove";g.feet=g.project.scenes.at("grove").spawn;g.update(idle,Tick);check(g.objectiveDone("keepers-errand",1),"map visit records objective");g.interact(npc("grove","merchant"));check(g.objectiveDone("keepers-errand",2),"NPC conversation records objective");press(Action::Attack);check(g.dialogueObject.empty()&&g.attackClock<0,"Space dismisses dialogue without attacking");
 check(g.giveItem("trail-bread",1)&&!g.objectiveDone("keepers-errand",3),"item objective checks quantity");check(g.giveItem("trail-bread",1)&&g.questState("keepers-errand")=="ready","all objectives make quest ready");
 std::string error,path=(std::filesystem::path(argv[2])/"quest-progress.dat").string();check(g.save(path,error),"active quest saves");StudioGame restored(argv[1]);check(restored.load(path,error)&&restored.questState("keepers-errand")=="ready","saved objectives restore");
 auto originalQuantity=restored.quests.at("keepers-errand").objectives[3].quantity;restored.quests.at("keepers-errand").objectives[3].quantity=3;check(!restored.load(path,error)&&restored.inventory==g.inventory,"changed objective definitions reject stale progress atomically");restored.quests.at("keepers-errand").objectives[3].quantity=originalQuantity;
 // Corrupt quest IDs must reject atomically, preserving inventory and event progress.
 std::ifstream input(path);std::string data((std::istreambuf_iterator<char>(input)),{});auto at=data.rfind("\"keepers-errand\"");check(at!=std::string::npos,"quest save fixture exists");data.replace(at,16,"\"unknown-quest\"");auto corrupt=(std::filesystem::path(argv[2])/"bad-quest.dat").string();std::ofstream(corrupt)<<data;check(!restored.load(corrupt,error)&&restored.questState("keepers-errand")=="ready"&&restored.inventory==g.inventory,"corrupt quest save rejects atomically");
 g.inventory["gold-coin"]=999;check(!g.completeQuest("keepers-errand")&&g.inventory.at("trail-bread")==2&&g.questState("keepers-errand")=="ready","reward capacity failure preserves turn-in items");g.inventory.erase("gold-coin");
 g.scene="meadow";g.feet=g.project.scenes.at("meadow").spawn;g.interact(npc("meadow","keeper"));press(Action::Interact);check(g.availableChoices().size()==3,"ready turn-in choice appears");press(Action::Interact);check(g.dialogueNode=="reward"&&g.questState("keepers-errand")=="completed","turn-in choice completes quest");check(!g.inventory.count("trail-bread")&&g.inventory.at("gold-coin")==5,"turn-in consumes items and awards reward");check(!g.completeQuest("keepers-errand")&&g.inventory.at("gold-coin")==5,"completed reward cannot be duplicated");press(Action::Interact);g.interact(npc("meadow","keeper"));check(g.availableChoices().size()==1,"completed-state dialogue appears");press(Action::Interact);check(g.dialogueNode=="thanks","completed branch advances");press(Action::Attack);
 check(g.save(path,error)&&restored.load(path,error)&&restored.questState("keepers-errand")=="completed","completed quests persist");check(!restored.completeQuest("keepers-errand")&&restored.inventory.at("gold-coin")==5,"load cannot duplicate reward");
 // Version 2 saves contain no quest section and reset the optional quest state.
 StudioGame fresh(argv[1]);check(fresh.save(path,error),"empty quest save written");std::ifstream old(path);data.assign(std::istreambuf_iterator<char>(old),{});auto v3data=data;v3data.replace(v3data.find("SAVE 4"),6,"SAVE 3");v3data.erase(v3data.size()-4);auto v3path=(std::filesystem::path(argv[2])/"v07-progress.dat").string();std::ofstream(v3path)<<v3data;check(restored.load(v3path,error),"v0.7 progress remains compatible");data.replace(data.find("SAVE 4"),6,"SAVE 2");data.erase(data.size()-6);auto legacy=(std::filesystem::path(argv[2])/"v06-progress.dat").string();std::ofstream(legacy)<<data;check(restored.load(legacy,error)&&restored.questProgress.empty(),"v0.6 progress remains compatible");
 // Delivery of an item that is also the reward handles capacity after consumption.
 StudioQuest q;q.name="Exchange";q.objectives={{"item","gold-coin",1}};q.rewardItem="gold-coin";q.rewardQuantity=1;fresh.quests["exchange"]=q;fresh.inventory["gold-coin"]=999;check(fresh.acceptQuest("exchange")&&fresh.completeQuest("exchange")&&fresh.inventory.at("gold-coin")==999,"same-item rewards use post-consumption capacity");
 g.interact(npc("meadow","keeper"));SoftwareRenderer render;render.render(g.draw(),g.atlas);render.writePPM((std::filesystem::path(argv[2])/"v07-dialogue.ppm").string());press(Action::Attack);press(Action::Journal);render.render(g.draw(),g.atlas);render.writePPM((std::filesystem::path(argv[2])/"v07-journal.ppm").string());check(render.pixels.size()==Width*Height,"dialogue choices and journal render natively");
 std::cout<<checks<<" story runtime checks passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
